sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

    var ga = new GlideAjax('ChangeRiskAjax');
    ga.addParam('sysparm_name', 'checkDangerSignals'); 
    ga.addParam('sysparm_ci_id', newValue); 

    ga.getXMLAnswer(function(response) {
        if (!response) {
            return;
        }

        var result = JSON.parse(response);

        if (result.hasP1) {
            g_form.addErrorMessage('WARNING: This CI is linked to an active P1 Incident.');
        }

        if (result.hasFailedChange) {
            g_form.addErrorMessage('WARNING: A recent change on this CI was unsuccessful in the last 7 days.');
        }
    });
}
